/* 按行读入 n×n 的原矩阵，一维下标是原行*n+原列。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, j = 0, n = 0;
    n = read();
    /* 输出位置 (i,j) 来自原位置 (n-1-j,i)，因此只需改变读取顺序。 */
    for (i = 0; i < (n * n); i += 1)  {
        a[i] = read();
    }
    for (i = 0; i < n; i += 1)  {
        for (j = 0; j < n; j += 1)  {
            /* 逐行输出旋转后的值，原数组不覆盖，也不构造第二个矩阵。 */
            emit(a[((((n - 1) - j) * n) + i)]);
        }
    }
    return 0;
}

