/* 按行读入 n×n 的原矩阵，一维下标是原行*n+原列。 */
use std::io:: {
    self, Read
}
;
fn mn(a: i32, b: i32) -> i32  {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32  {
    a.max(b)
}
fn emit(x: i32)  {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32)  {
    if n == 0  {
        print!("-");
    }
    for i in 0..n  {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader  {
    t: Vec<String>, p: usize,
}
impl Reader  {
    fn new() -> Self  {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self  {
            t: s.split_whitespace().map(String::from).collect(), p: 0,
        }
    }
    fn read(&mut self) -> i32  {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32  {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-"  {
            return 0;
        }
        for (i, c) in s.bytes().enumerate()  {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main()  {
    let mut reader = Reader::new();
    let mut a = vec![0i32;
    20000];
    let mut b = vec![0i32;
    20000];
    let mut d = vec![0i32;
    20000];
    let mut e = vec![0i32;
    20000];
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut n: i32 = 0;
    n = reader.read();
    i = 0;
    /* 输出位置 (i,j) 来自原位置 (n-1-j,i)，因此只需改变读取顺序。 */
    while i < (n * n)  {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    i = 0;
    while i < n  {
        j = 0;
        while j < n  {
            /* 逐行输出旋转后的值，原数组不覆盖，也不构造第二个矩阵。 */
            emit(a[((((n - 1) - j) * n) + i) as usize]);
            j += 1;
        }
        i += 1;
    }
}
